-- Oasis Shisha Lounge · esquema base (ejecutar en Supabase SQL Editor)
create type public.staff_role as enum ('admin','staff');
create type public.order_state as enum ('pending','received','preparing','ready','served','cancelled');
create table public.staff_profiles (id uuid primary key references auth.users(id) on delete cascade, role public.staff_role not null default 'staff', display_name text, created_at timestamptz not null default now());
create table public.tables (id uuid primary key default gen_random_uuid(), name text unique not null, public_token text unique not null default encode(gen_random_bytes(16),'hex'), active boolean not null default true, created_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), name text unique not null, position int not null default 0, active boolean not null default true);
create table public.products (id uuid primary key default gen_random_uuid(), category_id uuid references public.categories(id), name text not null, description text, price numeric(10,2) not null check(price>=0), active boolean not null default true, available boolean not null default true, featured boolean not null default false, position int not null default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.orders (id uuid primary key default gen_random_uuid(), public_token uuid unique not null default gen_random_uuid(), table_id uuid not null references public.tables(id), number bigint generated always as identity unique, status public.order_state not null default 'pending', subtotal numeric(10,2) not null check(subtotal>=0), discount numeric(10,2) not null default 0, total numeric(10,2) not null check(total>=0), idempotency_key uuid unique not null, notes text, created_at timestamptz not null default now());
create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id), product_name text not null, unit_price numeric(10,2) not null, quantity int not null check(quantity>0), line_total numeric(10,2) not null);
create table public.order_status_history (id bigint generated always as identity primary key, order_id uuid not null references public.orders(id) on delete cascade, status public.order_state not null, changed_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.roulette_campaigns (id uuid primary key default gen_random_uuid(), name text not null, active boolean not null default true, min_order_amount numeric(10,2) default 0, eligible_statuses public.order_state[] not null default '{served}', spins_per_order int not null default 1);
create table public.roulette_prizes (id uuid primary key default gen_random_uuid(), campaign_id uuid not null references public.roulette_campaigns(id), name text not null, weight int not null check(weight>0), active boolean not null default true, max_redemptions int, expires_days int default 30);
create table public.roulette_spins (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id), prize_id uuid references public.roulette_prizes(id), redemption_code text unique not null, created_at timestamptz not null default now(), unique(order_id));
create table public.prize_redemptions (id uuid primary key default gen_random_uuid(), spin_id uuid unique not null references public.roulette_spins(id), redeemed_by uuid references auth.users(id), redeemed_at timestamptz);
alter table public.staff_profiles enable row level security; alter table public.orders enable row level security; alter table public.products enable row level security; alter table public.tables enable row level security;
create policy "staff reads operational data" on public.orders for select to authenticated using (exists(select 1 from public.staff_profiles s where s.id=auth.uid()));
create policy "public reads active menu" on public.products for select using (active and available);
-- Las inserciones de pedidos, selección de premio y canje deben hacerse vía Edge Functions/RPC SECURITY DEFINER con validación de rol; no desde el navegador.
